/*
  Hand-written question bank, built from the lecture slides.
  k = kind: scenario | tf | fill | not | case | compare | fact
  q = question, o = options (first listed is NOT necessarily correct), a = index of correct option in o
  why = explanation shown after answering, eli = optional like-I'm-5 note, ref = slide reference
  True/false questions always use o: ["True","False"].
*/
window.PIL_QUESTIONS = {
1: [
{k:"fact", q:"According to the Britannica definition on the slides, law is created and enforced by…", o:["Governmental authorities","Religious leaders","International courts","Private companies"], a:0, why:"Britannica: rules created and enforced by governmental authorities to regulate the actions of citizens and of the government.", ref:"W1 s.12"},
{k:"compare", q:"Which dictionary defines law as 'a binding custom or practice of a community'?", o:["Merriam-Webster","Cambridge","Britannica","The ROC Constitution"], a:0, why:"Merriam-Webster includes binding custom, which is why its definition fits international law best: much of IL is custom.", ref:"W1 s.12"},
{k:"fill", q:"Cambridge: a law is a rule, ____ made by a government, used to order the way a society behaves.", o:["usually","always","never","only sometimes"], a:0, why:"'Usually' matters: law isn't always made by a government. International law is mostly made by states agreeing among themselves.", ref:"W1 s.12"},
{k:"fact", q:"Under Art. 170 ROC Constitution and Art. 4 Central Regulations Standards Act, a law must be…", o:["Passed by the Legislative Yuan and promulgated by the President","Approved by the Constitutional Court","Signed by the Premier and the Executive Yuan","Approved by a referendum"], a:0, why:"Taiwan's formal definition: 經立法院通過，總統公布.", eli:"The rule-making room votes yes, then the boss officially announces it.", ref:"W1 s.13"},
{k:"scenario", q:"The Legislative Yuan passes a bill but the President has not yet promulgated it. Under Taiwan's definition, is it law yet?", o:["No: it must also be promulgated by the President","Yes: passing it is enough","Yes, once the Executive Yuan agrees","No: it must also go to a referendum"], a:0, why:"Both steps are needed: passed by the Legislative Yuan AND promulgated by the President.", ref:"W1 s.13"},
{k:"scenario", q:"Two neighbours argue over who owns a fence, and a court decides. Which purpose of law is this?", o:["Resolving disputes","Establishing standards","Maintaining order","Protecting liberties and rights"], a:0, why:"Disputes are unavoidable; law gives a formal way to resolve them.", ref:"W1 s.14"},
{k:"scenario", q:"A rule says police cannot search your home without a warrant. Which purpose of law is this?", o:["Protecting liberties and rights","Resolving disputes","Establishing standards","Maintaining order"], a:0, why:"Law protects against unreasonable intrusions, including by government.", ref:"W1 s.14"},
{k:"scenario", q:"A speed limit sets the minimum acceptable behaviour for drivers. Which purpose does the slide call this?", o:["Establishing standards","Maintaining order","Resolving disputes","Protecting liberties and rights"], a:0, why:"Law as a 'guidepost for minimally acceptable behaviour in society'.", eli:"The lowest bar of OK behaviour.", ref:"W1 s.14"},
{k:"scenario", q:"Rules on queuing, traffic lights and curfews keep society from descending into chaos. Which purpose?", o:["Maintaining order","Establishing standards","Resolving disputes","Protecting liberties and rights"], a:0, why:"'Some semblance of order is necessary in a society and may be reflected in law.'", ref:"W1 s.14"},
{k:"not", q:"Which is NOT one of the four purposes of law on the slides?", o:["Maximising state power","Establishing standards","Resolving disputes","Protecting liberties and rights"], a:0, why:"The four: establishing standards, maintaining order, resolving disputes, protecting liberties and rights.", ref:"W1 s.14"},
{k:"tf", q:"According to the slides, law protects people against unreasonable intrusions by persons and organisations, but not by government.", o:["True","False"], a:1, why:"The slide says protection against violations by 'persons, organisations, or government'.", ref:"W1 s.14"},
{k:"case", q:"In the group exercise example, what did the 1895 Treaty of Shimonoseki do?", o:["Gave Japan sovereignty over Taiwan","Ended World War II in Asia","Created the Republic of China","Set Taiwan's territorial sea at 12 nautical miles"], a:0, why:"China (Qing) ceded Taiwan to Japan. It returns in Week 8's Taiwan history.", ref:"W1 s.10"},
{k:"fact", q:"How far does a state's territorial sovereignty extend from its coastal baseline (group exercise example)?", o:["12 nautical miles","24 nautical miles","200 nautical miles","3 nautical miles"], a:0, why:"The territorial sea: 12 nautical miles from the baseline.", eli:"Your yard goes 12 nautical miles into the sea.", ref:"W1 s.10"},
{k:"compare", q:"Why does the Merriam-Webster definition fit international law better than Britannica's?", o:["IL has no world government; much of it is binding custom","IL is always written by a legislature","IL is enforced by a world police force","IL only applies inside one country"], a:0, why:"Britannica needs governmental authorities to make and enforce law; IL has none, but binding custom fits.", ref:"W1 s.12"},
{k:"fact", q:"Who makes most of the rules of international law?", o:["The states themselves","A world parliament","The UN Secretary-General","The ICJ"], a:0, why:"The slides ask 'Who makes the law?'. For IL it's states, through treaties and custom (Week 2 develops this).", ref:"W1 s.15; W2 s.27"},
{k:"fact", q:"The class-participation mark (10%) is based on…", o:["The quality and frequency of in-class discussion","Attendance","The reflection notes","The group presentation"], a:0, why:"'Based on quality and frequency of in-class discussions (not attendance)'.", ref:"W1 s.9"},
{k:"fact", q:"What share of the final grade is the final exam?", o:["60%","20%","10%","50%"], a:0, why:"Participation 10%, reflection notes 10%, group presentation 20%, final exam 60%.", ref:"W1 s.9"},
{k:"fill", q:"Group exercise rule: don't name a treaty like the 'Stockholm Convention' unless you know its ____.", o:["function","date","number of parties","author"], a:0, why:"You had to write down each rule AND its function.", ref:"W1 s.10"},
{k:"not", q:"Which of these did the slides NOT use to define 'law'?", o:["The UN Charter","Britannica","Cambridge Dictionary","Merriam-Webster"], a:0, why:"Slides used Britannica, Cambridge, Merriam-Webster, plus ROC law.", ref:"W1 s.12–13"},
{k:"tf", q:"'Promulgated' means a law has been officially announced and brought into effect.", o:["True","False"], a:0, why:"In Taiwan, the President promulgates laws passed by the Legislative Yuan.", ref:"W1 s.13"}
],

2: [
{k:"fact", q:"In which year was the Peace of Westphalia?", o:["1648","1789","1919","1945"], a:0, why:"1648: often seen as the birth of the modern state system and state sovereignty.", ref:"W2 s.15"},
{k:"fact", q:"What did the Peace of Westphalia end?", o:["The Catholic–Protestant religious wars","World War I","The French Revolution","The colonisation of Africa"], a:0, why:"It ended the religious wars, recognised Protestant powers and states independent from churches.", ref:"W2 s.15"},
{k:"compare", q:"A Taiwanese and a French company dispute which country's law governs their contract. Which field is this?", o:["Private international law","Public international law","Jus cogens","International humanitarian law"], a:0, why:"Private IL concerns legal conflicts between individuals of different states. This course is only about public IL.", ref:"W2 s.9"},
{k:"tf", q:"This course covers both public and private international law.", o:["True","False"], a:1, why:"'This subject is only concerned with public IL.'", ref:"W2 s.9"},
{k:"compare", q:"The traditional (narrow) definition of PIL covers relations between…", o:["States only","States, IOs and some relationships with persons","Individuals of different states","Companies and governments"], a:0, why:"Narrow: rules binding on states in their relations with each other. The expansive definition adds IOs and some persons.", ref:"W2 s.10"},
{k:"fill", q:"The expansive definition covers states and IOs and their relations ____ (among themselves).", o:["inter se","erga omnes","jus cogens","pacta sunt servanda"], a:0, why:"Inter se = among themselves.", ref:"W2 s.10"},
{k:"fact", q:"Which other name for public international law appears on the slides?", o:["The law of nations","World law","Municipal law","Natural law"], a:0, why:"PIL is also known as 'the law of nations' because it mainly regulates conduct between states.", ref:"W2 s.9"},
{k:"not", q:"Which is NOT listed on the slides as a subject of international law?", o:["Political parties","Belligerents","International administrations","Individuals"], a:0, why:"Listed: states, international organisations, belligerents, international administrations, individuals.", ref:"W2 s.23"},
{k:"scenario", q:"State A breaks a trade treaty; State B responds by suspending its own obligations to A. Which principle explains B's reaction?", o:["Reciprocity","Consent","Pacta sunt servanda","Sovereign equality"], a:0, why:"Reciprocity: when a state breaches IL, it may face a reciprocal breach (by reprisal).", eli:"'I'll keep the rule as long as you do.'", ref:"W2 s.20"},
{k:"scenario", q:"A state refuses to follow a treaty it never signed, and IL agrees it doesn't have to. Which principle?", o:["Consent","Reciprocity","Monism","Universal jurisdiction"], a:0, why:"States are only bound by obligations they voluntarily agreed to. Treaties bind only parties.", ref:"W2 s.20"},
{k:"scenario", q:"A new government dislikes a treaty and stops performing it. Which principle says it must keep performing?", o:["Pacta sunt servanda","Reciprocity","Consent","Dualism"], a:0, why:"Agreements must be kept in good faith (Art. 26 VCLT).", eli:"A promise is a promise.", ref:"W2 s.21"},
{k:"fact", q:"Where is pacta sunt servanda codified?", o:["Art. 26 VCLT","Art. 27 VCLT","Art. 2(4) UN Charter","Art. 38 ICJ Statute"], a:0, why:"Art. 26 of the Vienna Convention on the Law of Treaties (1969).", ref:"W2 s.21, s.26"},
{k:"scenario", q:"A dualist state ratified a treaty but never passed implementing legislation. A citizen relies on the treaty in a national court. Likely position?", o:["The treaty binds the state internationally but has at most indirect effect inside","The treaty applies directly as national law","The treaty is void","The state is no longer bound internationally"], a:0, why:"In dualist states treaties bind 'on' the state but not 'in' it until domesticated.", ref:"W2 s.25"},
{k:"scenario", q:"Same state is sued internationally for not performing the treaty and argues: 'our parliament never passed the law'. Does that work?", o:["No: Art. 27 VCLT, domestic law is no excuse","Yes: dualism protects it","Yes, if it gives notice first","Only if the ICJ agrees"], a:0, why:"Art. 27 VCLT: domestic law is no justification for failing to perform a treaty.", ref:"W2 s.26"},
{k:"compare", q:"In which approach does international law apply directly, as if it were domestic law?", o:["Monism","Dualism","Legal positivism","Realism"], a:0, why:"Monist states make IL part of their domestic legal order.", ref:"W2 s.25"},
{k:"fact", q:"Which approach do most states in the world use?", o:["Dualism","Monism","Neither: IL never applies inside states","Both equally"], a:0, why:"'Most states in the world apply the dualist approach.'", ref:"W2 s.25"},
{k:"case", q:"Taiwan's 'Two Covenants' (ICCPR and ICESCR) have been domestically legislated. This is an example of…", o:["Domestication / transposition","A reservation","Accession","Persistent objection"], a:0, why:"Passing national law so the treaty applies inside the country.", ref:"W10 s.12; W2 s.25"},
{k:"not", q:"Which was NOT a way international law served European colonial expansion, per the slides?", o:["Banning the slave trade from the start","'Freedom of trade' enforced by threat or use of force","The conquest and appropriation of Africa","Protection and immunity for foreign nationals"], a:0, why:"IL was 'inhumane' at the time: the slave trade by European/American powers was lawful.", ref:"W2 s.17"},
{k:"fact", q:"Which developments followed WWII, per the slides?", o:["UN Charter, Nuremberg Trials, then decolonisation","Treaty of Versailles and the League of Nations","The Peace of Westphalia","The French Revolution"], a:0, why:"WWI → Versailles, League of Nations. WWII → UN Charter, Nuremberg, decolonisation.", ref:"W2 s.17"},
{k:"fact", q:"Which treaty assigned responsibility to defeated Germany after WWI?", o:["Treaty of Versailles","Peace of Westphalia","Treaty of Shimonoseki","Kellogg–Briand Pact"], a:0, why:"WWI: responsibility of defeated Germany (Treaty of Versailles).", ref:"W2 s.17"},
{k:"compare", q:"What did the French Revolution (1789–99) promote, per the slides?", o:["Self-determination, nationalism and equality among nations","A sovereign right to wage war for any reason","Religious control of states","Colonial tutelage"], a:0, why:"It challenged monarchy, spread republican ideals and influenced human rights and self-government.", ref:"W2 s.16"},
{k:"fact", q:"In the Middle Ages, which two religious legal traditions shaped international norms?", o:["Canon Law and Islamic international law","Roman law and Greek law","Common law and civil law","Natural law and positivism"], a:0, why:"They had distinct traditions but influenced each other.", ref:"W2 s.13"},
{k:"fact", q:"Who developed the 'Just War' concept, per the slides?", o:["St Augustine, later refined by Vitoria and Grotius","Kelsen and Brownlie","Hobbes and Rawls","Anghie and Gathii"], a:0, why:"Just War: St Augustine, later Francisco de Vitoria and Hugo Grotius.", ref:"W2 s.13"},
{k:"compare", q:"Breaking a moral rule (not a legal one) typically brings…", o:["A troubled conscience and social sanctions","Criminal punishment by a court","Termination of a treaty","An ICJ judgment"], a:0, why:"Violations of morality bring disturbance to individual conscience and social sanctions.", ref:"W2 s.5"},
{k:"tf", q:"Something can be immoral but still lawful.", o:["True","False"], a:0, why:"Yes. Historically the slave trade was lawful under European international law.", ref:"W2 s.8, s.17"},
{k:"compare", q:"When international law is violated, the main consequences are…", o:["Mainly political; courts exist but enforcement is often lacking","Criminal sanctions by a world police force","Automatic expulsion from the UN","Fines collected by the World Bank"], a:0, why:"No world government, court or police force. Consequences are primarily political.", ref:"W2 s.27–28"},
{k:"fill", q:"Why common rules? 'There can't be ____ different sets of procedures and standards.'", o:["200","20","2","2,000"], a:0, why:"Common rules facilitate international contact among ~200 states.", ref:"W2 s.18"},
{k:"fill", q:"In dualist states a treaty is binding ____ the state but not ____ the state without domestication.", o:["on / in","in / on","under / over","before / after"], a:0, why:"Binding 'on' states internationally; not binding 'in' them without domestication.", ref:"W2 s.25"},
{k:"compare", q:"Which source binds ALL states, based on general practice?", o:["Custom","Treaties","Reservations","Domestic legislation"], a:0, why:"Treaties bind only states that signed and ratified; custom binds all states.", ref:"W2 s.22"}
],

4: [
{k:"scenario", q:"A scholar argues genocide is prohibited even for a state that never agreed to any rule against it, because it is simply wrong. Which theory?", o:["Natural law","Legal positivism","Realism","Rational choice"], a:0, why:"Natural law: universal moral principles; rights and obligations exist independent of state consent.", eli:"Some things are just right or wrong.", ref:"W4 s.4"},
{k:"scenario", q:"'A rule is only law if states consented to it; morality is irrelevant.' Which theory?", o:["Legal positivism","Natural law","Feminist theory","TWAIL"], a:0, why:"Positivism: law derives authority from state consent, not morality.", ref:"W4 s.5"},
{k:"scenario", q:"'States obey international law only when it serves their power; otherwise they walk away.' Which theory?", o:["Realism","Natural law","Legal positivism","Feminist theory"], a:0, why:"Realism: IL shaped by power and national interest; states abandon agreements when power allows.", ref:"W4 s.6"},
{k:"scenario", q:"'State X joined the trade treaty because the tariff savings outweighed the cost of compliance.' Which theory?", o:["Rational choice","Realism","Natural law","TWAIL"], a:0, why:"Rational choice: states follow IL when benefits outweigh costs.", ref:"W4 s.7"},
{k:"scenario", q:"A critique says IL treats men as the norm and presents women as a deviation (e.g. 'vulnerable'). Which theory?", o:["Feminist theory","TWAIL","Realism","Legal positivism"], a:0, why:"Charlesworth, Chinkin, Wright: IL is male-dominated and patriarchal.", ref:"W4 s.8"},
{k:"scenario", q:"A critique says IL legitimised the subjugation of Third World peoples and isn't truly universal. Which approach?", o:["TWAIL","Rational choice","Natural law","Legal positivism"], a:0, why:"Third-World Approaches to International Law (Gathii, Anghie).", ref:"W4 s.11"},
{k:"compare", q:"Which theory is criticised because it 'can't fully explain the existence of jus cogens'?", o:["Legal positivism","Natural law","Feminist theory","TWAIL"], a:0, why:"Jus cogens binds states regardless of consent, which positivism struggles with.", ref:"W4 s.5"},
{k:"compare", q:"Which theory is criticised as subjective: 'who determines what is natural or moral?'", o:["Natural law","Realism","Rational choice","Legal positivism"], a:0, why:"Criticisms of natural law: no enforcement; subjectivity.", ref:"W4 s.4"},
{k:"fact", q:"Hans Kelsen and Ian Brownlie are associated on the slides with…", o:["Legal positivism","Natural law","TWAIL","Feminist theory"], a:0, why:"Brownlie: true law is made by authority. Kelsen: legitimacy from formal legal rules.", ref:"W4 s.5"},
{k:"fact", q:"What does 'anarchy' mean in realist theory?", o:["No central authority above states","Constant war between states","No treaties exist","Rule by the UN"], a:0, why:"International relations lack a central authority, so states maximise power to survive.", ref:"W4 s.6"},
{k:"not", q:"Which is NOT a slide example of a non-European system of inter-polity relations?", o:["The Peace of Westphalia","The Ming Dynasty tributary system","The Treaty of Nara","The Capitulations of the Ottoman Empire"], a:0, why:"Westphalia is the classic European origin story. The others show IL-like systems existed elsewhere.", ref:"W4 s.9"},
{k:"case", q:"'Terra nullius' was used when…", o:["Britain established sovereignty in Canada and Australia","The UN admitted Switzerland","Norway drew its fishing baselines","Kosovo declared independence"], a:0, why:"Treating land lived on by Indigenous peoples as 'nobody's land'.", ref:"W4 s.13"},
{k:"case", q:"Vitoria argued Indigenous Americans had sovereignty and land ownership, yet Spain still had…", o:["A 'limited right' to rule them","No rights at all in the Americas","A duty to leave immediately","Only trading rights"], a:0, why:"Because they were supposedly 'unsuited' to administering a legitimate government.", ref:"W4 s.14"},
{k:"scenario", q:"Newly independent states nationalised foreign-owned mines. What compensation standard did former colonial powers demand?", o:["'International standards' under international custom","The new state's national law","No compensation at all","A standard set by the UN General Assembly"], a:0, why:"New states argued for national law; former colonial powers insisted on 'international standards'.", ref:"W4 s.16"},
{k:"case", q:"In the Reparations case (1949), the ICJ held that the UN…", o:["Has international legal personality, valid even against non-members","Has no legal personality of its own","Can only be sued in US courts","Is a state"], a:0, why:"Personality was essential for its functions, and objective: valid even towards non-members.", eli:"The club counts even for houses that didn't join.", ref:"W4 s.26–27"},
{k:"tf", q:"Oppenheim's view that ONLY states are subjects of international law is now considered too restrictive.", o:["True","False"], a:0, why:"IL increasingly covers non-state actors: IOs, individuals, groups, companies.", ref:"W4 s.19"},
{k:"not", q:"Which capacity do individuals generally NOT have in international law?", o:["Making treaties or creating customary law","Rights under human rights law","Responsibility for war crimes","Complaining to UN treaty bodies"], a:0, why:"Individuals cannot participate in treaty-making or the creation of custom.", ref:"W4 s.21, s.28"},
{k:"scenario", q:"A pirate from Country A is caught on the high seas by Country B's navy. Can B put him on trial?", o:["Yes: piracy is a crime of universal jurisdiction","No: only Country A can","Only with Security Council approval","Only at the ICJ"], a:0, why:"A pirate is hostis humani generis; any state may arrest and try them.", ref:"W4 s.29"},
{k:"compare", q:"Which permanent court (since 2002) tries individuals for crimes in the Rome Statute?", o:["International Criminal Court","International Court of Justice","Tribunal for the former Yugoslavia","Permanent Court of Arbitration"], a:0, why:"ICC = individuals. ICJ = disputes between states.", ref:"W4 s.30"},
{k:"fact", q:"Which were ad hoc tribunals set up for specific situations?", o:["Former Yugoslavia, Rwanda, Sierra Leone","ICC, ICJ, WTO","ECtHR, IACtHR, African Court","PCA, ITLOS, ICJ"], a:0, why:"Before the ICC, tribunals had competence over specific situations only.", ref:"W4 s.30"},
{k:"fact", q:"Is there an express hierarchy among the Art. 38(1) sources?", o:["No, but treaties and custom are the two most important","Yes: treaties, then custom, then principles","Yes: custom always beats treaties","Yes: judicial decisions come first"], a:0, why:"An earlier draft said 'successively', but that word isn't in the final text.", ref:"W4 s.34"},
{k:"fill", q:"Judicial decisions and teachings of publicists are ____ means for determining rules of law.", o:["subsidiary","primary","binding","peremptory"], a:0, why:"Art. 38(1)(d): helpers for finding the law, not sources themselves.", ref:"W4 s.33"},
{k:"scenario", q:"State X ratified a treaty last year, but the treaty needs 35 ratifications and has only 20. Is X bound yet?", o:["No: the treaty hasn't entered into force","Yes: ratification is enough","Yes, but only partly","No: X must also accede"], a:0, why:"Two criteria: consent to be bound AND entry into force.", ref:"W4 s.37"},
{k:"scenario", q:"State Y didn't take part in negotiating a treaty but wants to join it now. How does it usually consent?", o:["Accession","Ratification","Reservation","Signature only"], a:0, why:"Non-negotiating states usually express consent by accession.", eli:"Joining the game later.", ref:"W4 s.38"},
{k:"scenario", q:"Two states sign a border treaty. Must third states respect that border?", o:["Yes: dispositive treaties create regimes valid erga omnes","No: treaties never affect third states","Only if they sign the treaty too","Only UN members must"], a:0, why:"Exception to 'binding only on parties': territorial treaties must in practice be recognised by all.", ref:"W4 s.36"},
{k:"fact", q:"The VCLT applies to treaties that are…", o:["Between states and in written form","Between any entities, oral or written","Between IOs only","Regional only"], a:0, why:"The VCLT applies only to treaties between states, in written form.", ref:"W4 s.40"},
{k:"scenario", q:"A treaty banning a practice enters into force in 2020. Can it be used to condemn that practice done in 2015?", o:["No: non-retroactivity, unless the parties agreed otherwise","Yes: treaties always apply backwards","Yes, if custom agrees","Only for non-parties"], a:0, why:"Treaties regulate relations from entry into force onwards.", ref:"W4 s.42"},
{k:"case", q:"Singapore joined the CRPD with a reservation on Art. 25 about…", o:["Private health and life insurers","Military service","Voting rights","Education"], a:0, why:"It reserved on the provision of health and life insurance by private insurers.", ref:"W4 s.44"},
{k:"tf", q:"A reservation is valid even if it is incompatible with the treaty's object and purpose.", o:["True","False"], a:1, why:"A reservation must NOT be incompatible with the object and purpose.", ref:"W4 s.43"},
{k:"compare", q:"How do 'acceptance' and 'approval' compare with ratification?", o:["Same legal effect as ratification","Weaker: they don't bind","Stronger: they can't be withdrawn","They are only for regional treaties"], a:0, why:"Acceptance and approval have the same legal effect as ratification.", ref:"W4 s.38"}
],

6: [
{k:"compare", q:"Which pair are the two elements of customary international law?", o:["General state practice + opinio juris","Signature + ratification","A treaty + a court decision","Consent + reciprocity"], a:0, why:"Practice (what states do) + opinio juris (belief it is legally required).", ref:"W6 s.5"},
{k:"scenario", q:"States always send condolences when a foreign leader dies, purely out of politeness. Is that custom?", o:["No: without opinio juris it is mere courtesy","Yes: practice alone is enough","Yes, once it lasts 100 years","Only if a treaty says so"], a:0, why:"Both elements are needed. Diplomatic immunity counts because states see it as legally obligatory, 'not just a matter of courtesy'.", ref:"W6 s.5, s.8"},
{k:"tf", q:"A custom needs a long minimum period of time to form.", o:["True","False"], a:1, why:"No particular duration: rules on airspace and the continental shelf became custom quickly.", ref:"W6 s.5"},
{k:"case", q:"Why did Norway win the Anglo-Norwegian Fisheries case (ICJ, 1951)?", o:["Continuous state practice and no objection from other states","The UK signed a treaty agreeing to the lines","Norway was a specially affected state with a larger navy","The lines followed the general direction of the coast exactly"], a:0, why:"The Court cited Norway's continuous practice and lack of objection by other states.", ref:"W6 s.7"},
{k:"case", q:"What was disputed in the Anglo-Norwegian Fisheries case?", o:["Norway's method of drawing baselines for its territorial waters","Norway's claim to Greenland","UK fishing quotas in the EU","A collision between fishing boats"], a:0, why:"Norway's 1933 decree on exclusive fishing rights and baselines along a coast of fjords and islands.", ref:"W6 s.7"},
{k:"fact", q:"In court, whose practice counts most when assessing a custom (North Sea Continental Shelf, 1969)?", o:["Specially affected states","The five permanent SC members","The oldest states","States that signed the VCLT"], a:0, why:"E.g. coastal states for rules about the sea.", ref:"W6 s.5"},
{k:"case", q:"The customary rule of diplomatic immunity was later codified in…", o:["The Vienna Convention on Diplomatic Relations (1961)","The UN Charter (1945)","The Montevideo Convention (1933)","The Rome Statute (1998)"], a:0, why:"Custom first, treaty later.", ref:"W6 s.8"},
{k:"case", q:"What shows state practice against genocide BEFORE the 1948 Genocide Convention?", o:["The Nuremberg Trials","The Peace of Westphalia","The Kellogg–Briand Pact","The Fisheries case"], a:0, why:"States condemned and prosecuted genocide even before the Convention.", ref:"W6 s.9"},
{k:"scenario", q:"A refugee flees persecution. State Z, not party to the 1951 Refugee Convention, plans to send them back. What rule stops it?", o:["Non-refoulement, as customary law","Nothing: Z never signed the treaty","Pacta sunt servanda","Diplomatic immunity"], a:0, why:"Non-refoulement binds even non-signatories as custom.", eli:"You can't push the kid back out to the bully.", ref:"W6 s.10"},
{k:"scenario", q:"While a new custom was forming, State P clearly and repeatedly objected. Now it says the rule doesn't bind it. Right?", o:["Yes: it is a persistent objector","No: custom binds every state","Only if it signs a treaty","Only if the ICJ agrees"], a:0, why:"A clear, persistent objection during formation can exempt a state (not from jus cogens).", ref:"W6 s.11"},
{k:"scenario", q:"State Q stayed silent while a custom formed and only objects now. Is it bound?", o:["Yes: silence is presumed acceptance","No: it is a persistent objector","No, because it objects now","Only if it is a large state"], a:0, why:"Objection must be clear and during formation; otherwise acceptance is presumed.", ref:"W6 s.11"},
{k:"scenario", q:"Two states sign a treaty to replace a general custom between themselves (not jus cogens). Effect?", o:["The treaty governs them; the custom still binds everyone else","The custom is abolished worldwide","The treaty is void","They are bound by neither"], a:0, why:"Derogation by treaty: 'contracting out' between the signatories.", ref:"W6 s.12"},
{k:"scenario", q:"Two states sign a treaty allowing slavery between them. Is it valid?", o:["No: it is void because it conflicts with jus cogens","Yes, between the parties","Yes, if registered at the UN","Yes, as a regional custom"], a:0, why:"A treaty provision contrary to jus cogens is void.", ref:"W6 s.14"},
{k:"case", q:"To prove a regional custom (e.g. diplomatic asylum in Latin America), the claimant must show the other state…", o:["Specifically and positively accepted it as law","Stayed silent","Is in the same region","Is a UN member"], a:0, why:"Stricter proof than general custom: tacit consent is not enough.", ref:"W6 s.13"},
{k:"not", q:"Which is NOT on the slides' list of least controversial jus cogens prohibitions?", o:["Violating diplomatic immunity","Genocide","Apartheid","Slavery"], a:0, why:"List: crimes against humanity, genocide, piracy, apartheid, slavery, use of force except self-defence.", ref:"W6 s.15"},
{k:"compare", q:"All jus cogens is custom. Is all custom jus cogens?", o:["No: only fundamental norms that allow no derogation","Yes, always","Only European custom","Only once codified in a treaty"], a:0, why:"Custom can change through practice and treaties; jus cogens cannot be altered.", ref:"W6 s.14"},
{k:"fill", q:"Jus cogens applies erga omnes, which means ____.", o:["towards all","between parties only","agreements must be kept","among themselves"], a:0, why:"Erga omnes = owed towards all.", ref:"W6 s.14"},
{k:"not", q:"Which is NOT listed as a source of evidence for custom?", o:["Newspaper editorials","GA resolutions on legal questions","Practice of international organisations","States' policy statements"], a:0, why:"Also listed: court decisions and extensive patterns of treaties.", ref:"W6 s.16"},
{k:"scenario", q:"Between two treaty parties, a treaty rule and a custom rule conflict (not jus cogens). Which prevails between them?", o:["The treaty","The custom","Neither: both are void","Whichever is older"], a:0, why:"No strict hierarchy, but between the parties a treaty prevails over custom.", ref:"W6 s.17"},
{k:"fact", q:"Where do 'general principles of law' come from?", o:["Principles found in domestic legal systems, adapted by analogy","UN General Assembly resolutions","The ICJ's own decisions","Treaties signed by all states"], a:0, why:"'General principles of municipal jurisprudence' (Oppenheim), with no mechanical copying.", ref:"W6 s.18"},
{k:"tf", q:"In theory, international courts make international law.", o:["True","False"], a:1, why:"In theory courts apply the law, not make it. Decisions are evidence of the law.", ref:"W6 s.19"},
{k:"compare", q:"Who can be sovereign?", o:["Only states","States and IOs","Any group with territory","Individuals"], a:0, why:"Sovereignty is an attribute of statehood.", ref:"W6 s.21"},
{k:"not", q:"Which is NOT a slide example of a limit on sovereignty?", o:["The right to hold national elections","Responsibility for injuries to aliens","Diplomatic immunity","Equitable use of water resources"], a:0, why:"IL can limit state power even inside its own territory.", ref:"W6 s.23"},
{k:"scenario", q:"Argentina and Chile agreed in 1971 to send their Beagle Channel island dispute to binding arbitration. Which form of consent?", o:["Special agreement","Jurisdictional clause in a treaty","Optional clause","Forum prorogatum"], a:0, why:"Ad hoc consent for one specific dispute.", ref:"W6 s.25"},
{k:"scenario", q:"Art. IX of the Genocide Convention gives the ICJ jurisdiction over disputes under it. Which form of consent?", o:["Jurisdictional clause in a treaty","Special agreement","Optional clause","Persistent objection"], a:0, why:"Consent given in advance inside a treaty.", ref:"W6 s.25"},
{k:"compare", q:"Which describes public international law's structure?", o:["Horizontal: sovereign equals, no central authority","Vertical: top-down with compulsory courts","Vertical: run by the UN Security Council","Horizontal, but with a world police force"], a:0, why:"Domestic law is vertical; PIL is horizontal, with decentralised enforcement.", ref:"W6 s.26"},
{k:"scenario", q:"Liechtenstein has a tiny population. Does that stop it being a state?", o:["No: there is no minimum population size","Yes: it needs at least one million people","Yes, unless it joins the UN","Only if its territory is also small"], a:0, why:"Microstates (Liechtenstein, San Marino, Monaco, Andorra) are states.", ref:"W6 s.32"},
{k:"scenario", q:"Israel's borders were unsettled when it declared independence. Was it treated as a state?", o:["Yes: perfect borders aren't required","No: borders must be fully delimited","Only after a peace treaty","Only after UN membership"], a:0, why:"North Sea: 'no rule that the land frontiers must be fully delimited'.", ref:"W6 s.34–35"},
{k:"scenario", q:"Lebanon was partitioned in practice during civil war. Did it stop being a state?", o:["No: temporary loss of effective government doesn't end statehood","Yes: it became a 'failed state' in law","Yes, until a new constitution","Only if the UN suspended it"], a:0, why:"'Failed State' is not a legal concept.", ref:"W6 s.36"},
{k:"case", q:"After the Tinoco regime fell, Costa Rica's new government cancelled its contracts. What did the arbitrator hold?", o:["The contracts bound later governments: Tinoco was the de facto ruler","They were void because Tinoco was unconstitutional","They were void because Britain never recognised Tinoco","Costa Rica could choose"], a:0, why:"A change of government doesn't change the state's obligations; recognition doesn't decide personality.", ref:"W6 s.37"},
{k:"fact", q:"The Montevideo Convention has only 15 ratifications. Why does it matter for everyone?", o:["It codifies existing custom on statehood","The UN adopted it as binding","It is jus cogens","All states acceded later"], a:0, why:"Regarded as codifying existing customary rules of statehood.", ref:"W6 s.30"},
{k:"compare", q:"The USA didn't recognise the Soviet government until 1933. This is used to criticise…", o:["The constitutive theory","The declaratory theory","The persistent objector rule","Pacta sunt servanda"], a:0, why:"Recognition is political; it would be absurd to say the USSR wasn't a state for a decade.", ref:"W6 s.46"}
],

8: [
{k:"case", q:"What did the General Assembly ask the ICJ about Kosovo in 2008?", o:["Whether the unilateral declaration of independence was in accordance with international law","Whether Kosovo is a state","Whether NATO's 1999 bombing was lawful","Whether Serbia committed genocide"], a:0, why:"The question was about the legality of the declaration, not statehood.", ref:"W8 s.17"},
{k:"tf", q:"In 2010 the ICJ held that Kosovo is a state.", o:["True","False"], a:1, why:"It held only that the declaration did not violate international law.", ref:"W8 s.18"},
{k:"fact", q:"How many UN members recognise Kosovo, per the slides?", o:["99 of 193","12 of 193","178 of 193","193 of 193"], a:0, why:"99 out of 193.", ref:"W8 s.16"},
{k:"case", q:"What does the 2013 Kosovo–Serbia First Agreement show?", o:["Serbia accepts Kosovo's factual independence without recognising it","Serbia formally recognised Kosovo","Kosovo rejoined Serbia","The UN admitted Kosovo"], a:0, why:"It doesn't settle status or imply recognition, but dismantles Serbia's public power in northern Kosovo.", ref:"W8 s.19"},
{k:"case", q:"What did UNGA Resolution 2758 (1971) decide?", o:["Who represents China at the UN; it is silent on Taiwan","That Taiwan is part of the PRC","That Taiwan is a state","That the ROC keeps the SC seat"], a:0, why:"It seated the PRC as China's only representative. It doesn't mention Taiwan.", ref:"W8 s.23–24"},
{k:"fact", q:"How many states officially recognise the ROC (Taiwan), per the slides?", o:["12","51","99","178"], a:0, why:"12 official recognitions, quasi-official relations with almost every state.", ref:"W8 s.25–26"},
{k:"compare", q:"Which verb describes the US position on 'one China'?", o:["Acknowledges","Respects","Adheres to","Rejects"], a:0, why:"US 'acknowledges' (three communiqués, Taiwan Relations Act); Japan 'respects'.", ref:"W8 s.26"},
{k:"fact", q:"What is Taiwan's name at the WTO?", o:["Separate Customs Territory of Taiwan, Penghu, Kinmen and Matsu","Chinese Taipei","Republic of China","Taiwan Province"], a:0, why:"'Chinese Taipei' is the name in international sport.", ref:"W8 s.28"},
{k:"scenario", q:"The American Institute in Taiwan isn't called an embassy but performs embassy functions. Which statehood criterion does this support?", o:["Capacity to enter into relations with other states","Permanent population","Defined territory","Government"], a:0, why:"Evidence of Taiwan's formal, informal and de facto relations with states.", ref:"W8 s.27"},
{k:"tf", q:"Political recognition is one of the legal criteria of statehood.", o:["True","False"], a:1, why:"Political recognition is not a criterion under IL; IL follows factual reality.", ref:"W8 s.29"},
{k:"fact", q:"Generally, an international organisation has members from at least how many states?", o:["Three","Two","Ten","Fifty"], a:0, why:"At least three states, activities in several states, a formal agreement.", ref:"W8 s.31"},
{k:"not", q:"Which of these is NOT an inter-governmental organisation (IGO)?", o:["International Olympic Committee","United Nations","World Health Organization","NATO"], a:0, why:"The IOC is an international organisation, but not an IGO.", ref:"W8 s.32"},
{k:"scenario", q:"On a substantive UNSC resolution, 14 members vote yes and France votes no. Result?", o:["It fails: France used its veto","It passes: 14 is more than 9","It passes, but isn't binding","It goes to the General Assembly"], a:0, why:"Substantive matters need 9 votes including the concurring votes of all P5.", ref:"W8 s.57"},
{k:"scenario", q:"On a procedural UNSC vote, 9 members vote yes and China votes no. Result?", o:["It passes: procedural matters need 9 votes, no veto","It fails: China vetoed","It fails: unanimity is needed","It goes to the ICJ"], a:0, why:"The veto applies only to substantive matters.", ref:"W8 s.57"},
{k:"fact", q:"What majority do 'important questions' (e.g. budget, admissions) need in the General Assembly?", o:["Two-thirds of members present and voting","Simple majority","Unanimity","9 of 15"], a:0, why:"Other questions need a simple majority.", ref:"W8 s.55"},
{k:"fact", q:"Who admits new UN members?", o:["The General Assembly, on the Security Council's recommendation","The Security Council alone","The Secretary-General","The ICJ"], a:0, why:"Art. 4(2) UN Charter.", ref:"W8 s.52"},
{k:"tf", q:"A UN member has been expelled under Art. 6 for persistently violating the Charter.", o:["True","False"], a:1, why:"No suspension under Art. 5 or expulsion under Art. 6 has ever been taken.", ref:"W8 s.52"},
{k:"fact", q:"How is the UN Secretary-General appointed?", o:["By the GA on the SC's recommendation, five-year renewable term","Elected directly by all states for life","Chosen by the ICJ","Appointed by the host state"], a:0, why:"Election effectively needs P5 approval.", ref:"W8 s.60"},
{k:"scenario", q:"Qatar and Bahrain sought to agree to refer their maritime dispute to the ICJ. Which consent method?", o:["Special agreement","Optional clause","Treaty clause","Forum prorogatum"], a:0, why:"States conclude an agreement to refer a dispute.", ref:"W8 s.66"},
{k:"scenario", q:"Australia accepts ICJ compulsory jurisdiction for all matters except maritime-zone disputes. Which consent method?", o:["Optional clause declaration (Art. 36(2))","Special agreement","Forum prorogatum","Treaty clause"], a:0, why:"74 states have accepted compulsory jurisdiction this way.", ref:"W8 s.68"},
{k:"scenario", q:"State A sues State B. B hadn't accepted jurisdiction, but then takes part and argues the merits. What is this?", o:["Forum prorogatum","Special agreement","An advisory opinion","Persistent objection"], a:0, why:"Consent given after proceedings start.", ref:"W8 s.69"},
{k:"compare", q:"What does the slash in 'Benin/Niger' (vs 'Nicaragua v. Colombia') tell you?", o:["The case was filed by special agreement","It was a unilateral application","It is an advisory opinion","It is a criminal case"], a:0, why:"Special agreement = slash; application by one state against another = 'v.'.", ref:"W8 s.70"},
{k:"tf", q:"A state can ask the ICJ for an advisory opinion.", o:["True","False"], a:1, why:"Only 5 UN organs and 16 specialised agencies can request them.", ref:"W8 s.71"},
{k:"fact", q:"Who may ask the ICJ for an advisory opinion on 'any legal question'?", o:["The General Assembly and the Security Council","Any UN member state","Any specialised agency","The Secretary-General only"], a:0, why:"Other organs and agencies only on questions within the scope of their activities.", ref:"W8 s.71"},
{k:"fact", q:"How many judges sit on the ICJ, and for how long?", o:["15 judges, nine-year terms","9 judges, fifteen-year terms","15 judges, for life","5 judges, five-year terms"], a:0, why:"Elected by the GA and SC; no two from the same state.", ref:"W8 s.72"},
{k:"fact", q:"The UN Human Rights Council was created in…, with how many members?", o:["2006, 47 states","1945, 15 states","1948, 193 states","2006, 193 states"], a:0, why:"Created by the GA in 2006; 47 states elected by the GA.", ref:"W8 s.58"},
{k:"compare", q:"The ILC drafts rules on a subject where custom is non-existent or insufficiently developed. Which function?", o:["Progressive development","Codification","Adjudication","Ratification"], a:0, why:"Codification = writing down existing rules; progressive development = new rules.", ref:"W8 s.77"},
{k:"fact", q:"Which Charter article obliges all members to accept and carry out SC decisions?", o:["Art. 25","Art. 2(4)","Art. 51","Art. 92"], a:0, why:"Art. 25 makes SC decisions binding.", ref:"W8 s.57"},
{k:"scenario", q:"The UN wants to intervene in a matter purely within a state's domestic jurisdiction, not under Chapter VII. Allowed?", o:["No: Art. 2(7) protects domestic jurisdiction","Yes, always","Yes, if the GA votes for it","Yes, if the ICJ advises it"], a:0, why:"The exception is Chapter VII enforcement measures.", ref:"W8 s.51"},
{k:"fact", q:"Which UN principal organ is no longer operational?", o:["The Trusteeship Council","ECOSOC","The Secretariat","The ICJ"], a:0, why:"Its task of supervising trust territories is finished.", ref:"W8 s.53"}
],

9: [
{k:"compare", q:"'Was the invasion legal in the first place?' falls under…", o:["Jus ad bellum","Jus in bello","Jus cogens","Erga omnes"], a:0, why:"Jus ad bellum = legality of going to war. Jus in bello = conduct during war (IHL).", eli:"Rulebook 1: may you start the fight?", ref:"W9 s.4"},
{k:"fact", q:"What was the 1928 Kellogg–Briand Pact?", o:["The first attempt to outlaw war completely","The League of Nations' founding treaty","A UN Security Council resolution","A Geneva Convention"], a:0, why:"Parties renounced war as an instrument of national policy.", ref:"W9 s.9"},
{k:"case", q:"What did Japan's invasion of Manchuria (1931) reveal about the Kellogg–Briand Pact?", o:["There was no way to enforce it","It worked perfectly","Japan had not signed it","It only covered Europe"], a:0, why:"Japan had signed, but no one enforced it.", ref:"W9 s.10"},
{k:"fact", q:"Under Art. 12 of the League Covenant, members agreed not to go to war until…", o:["Three months after the award, judicial decision or Council report","The UN Security Council approved","One year after a declaration of war","Never"], a:0, why:"A cooling-off period, not a ban.", ref:"W9 s.8"},
{k:"tf", q:"The 1919 League Covenant completely outlawed war.", o:["True","False"], a:1, why:"Members could still go to war under certain conditions (Arts. 12, 15(7)).", ref:"W9 s.7"},
{k:"tf", q:"Art. 2(4) bans the actual use of force but not the threat of force.", o:["True","False"], a:1, why:"It prohibits both the threat and the use of force.", ref:"W9 s.15"},
{k:"scenario", q:"State A runs a large propaganda and economic pressure campaign against B, with no physical violence. Is this 'armed force' under Art. 2(4)?", o:["No: actions without physical violence don't count","Yes: any pressure is force","Yes, if it lasts long enough","Only if the SC says so"], a:0, why:"Economic aggression, information warfare and propaganda are not armed force.", ref:"W9 s.16"},
{k:"scenario", q:"A state says a brief border skirmish didn't breach Art. 2(4) because it took no territory. Is that accepted?", o:["No: the accepted reading bans all force unless the Charter allows it","Yes: only taking land is banned","Yes, if it lasts under a day","Only if the UN agrees"], a:0, why:"The permissive reading is not accepted by states or scholars.", ref:"W9 s.18–19"},
{k:"fact", q:"What supports the strict reading of Art. 2(4)?", o:["The Charter's preparatory work: the words were added to protect small states","A 2005 GA resolution","The Kellogg–Briand Pact","The Bush Doctrine"], a:0, why:"The phrasing guaranteed small states; it wasn't meant to be permissive.", ref:"W9 s.20"},
{k:"scenario", q:"The SC imposes an arms embargo and a trade ban on a state. Which Charter article?", o:["Art. 41","Art. 42","Art. 51","Art. 2(4)"], a:0, why:"Art. 41 = non-military measures.", ref:"W9 s.22"},
{k:"scenario", q:"The SC authorises members to use 'all necessary means' to restore a state's sovereignty. Which article?", o:["Art. 42","Art. 41","Art. 51","Art. 25"], a:0, why:"Art. 42 = military action when Art. 41 is or would be inadequate.", ref:"W9 s.23"},
{k:"case", q:"Resolution 678 gave Iraq a deadline to leave Kuwait. When was it?", o:["15 January 1991","2 August 1990","16 January 1991","19 March 2003"], a:0, why:"Desert Storm began the next day, 16 January 1991.", ref:"W9 s.26–27"},
{k:"case", q:"What did Resolution 1973 (2011) set up over Libya?", o:["A no-fly zone to protect civilians","A UN-run government","A blockade of all ports","An ICC trial of Gaddafi"], a:0, why:"With exceptions for humanitarian flights and evacuations; 'all necessary measures' to enforce it.", ref:"W9 s.29"},
{k:"case", q:"What is the main criticism of the 2011 Libya intervention?", o:["It became regime change without a post-conflict plan","It had no SC authorisation","NATO never took part","It happened before any protests"], a:0, why:"The power vacuum led to militias, ISIS and ongoing conflict.", ref:"W9 s.30"},
{k:"case", q:"Mali: which mission did Resolution 2085 authorise, and how did MINUSMA end?", o:["AFISMA; MINUSMA withdrew in 2023 after the junta asked it to leave","MINUSMA; AFISMA was expelled","NATO; it is still there","AFISMA; it became a NATO mission"], a:0, why:"Res. 2085 (2012) → AFISMA; Res. 2100 (2013) → MINUSMA; withdrawn by Dec 2023.", ref:"W9 s.32–33"},
{k:"scenario", q:"State A bombs State B because intelligence suggests B might attack next year. Lawful under Art. 51?", o:["No: no armed attack has occurred","Yes: anticipatory self-defence is allowed by the Charter","Yes, if A reports it to the SC","Yes, under Art. 42"], a:0, why:"The Charter requires an armed attack to actually occur.", ref:"W9 s.36–37"},
{k:"fact", q:"How long may a state act in self-defence under Art. 51?", o:["Until the Security Council has taken the necessary measures","Indefinitely","Exactly 30 days","Until the GA votes"], a:0, why:"Self-defence is temporary; it must also be reported immediately.", ref:"W9 s.35, s.39"},
{k:"case", q:"What does the Caroline test require for customary self-defence?", o:["An immediate, pressing threat with no alternative, and proportional force","SC authorisation and a declaration of war","Any threat to national interests","Recognition by the GA"], a:0, why:"From the Webster–British correspondence.", ref:"W9 s.40"},
{k:"compare", q:"Which principle decides HOW MUCH force may be used in self-defence?", o:["Proportionality","Necessity","Reciprocity","Distinction"], a:0, why:"Necessity = whether force may be used; proportionality = how much.", ref:"W9 s.43"},
{k:"scenario", q:"Terrorists cross from State A into State B. What may B lawfully do?", o:["Use force to arrest or expel the terrorists, not attack State A","Attack State A's army in retaliation","Bomb State A's capital","Nothing at all"], a:0, why:"Self-defence doesn't include armed reprisal.", ref:"W9 s.47"},
{k:"case", q:"What did the ICJ's Nuclear Weapons Advisory Opinion (1996) say about armed reprisals?", o:["They are unlawful","They are lawful if proportionate","They are a form of self-defence","They need GA approval"], a:0, why:"Armed reprisals 'are considered to be unlawful'.", ref:"W9 s.47"},
{k:"case", q:"Why does the 2003 Iraq war fail as self-defence?", o:["No armed attack, no imminent threat, and no WMDs","Iraq had attacked the US on 9/11","The SC authorised it","The UK Attorney-General approved it"], a:0, why:"Neither self-defence nor SC-authorised: unlawful, per most scholars.", ref:"W9 s.50–52"},
{k:"scenario", q:"A state invades to 'enforce' old SC resolutions, without any new authorisation. Per the slides?", o:["Not allowed: enforcing SC resolutions is the SC's job","Allowed: any state may enforce them","Allowed if it was a P5 member","Allowed under Art. 51"], a:0, why:"This was the US argument about weapons inspectors in Iraq.", ref:"W9 s.50"},
{k:"compare", q:"Iraq 2003 involved a coalition of many states. Unilateral or collective use of force?", o:["Unilateral: it's about authority and purpose, not numbers","Collective: many states took part","Collective, because the UK joined","Neither"], a:0, why:"Collective = decided by an authorised body like the UN (e.g. Kuwait 1991).", ref:"W9 s.54–55"},
{k:"fact", q:"Which treaty article makes an armed attack on one ally an attack on all?", o:["Art. 5 North Atlantic Treaty","Art. 51 UN Charter","Art. 42 UN Charter","Art. 12 League Covenant"], a:0, why:"Collective self-defence is the basis of alliances like NATO.", ref:"W9 s.56"},
{k:"fact", q:"What must happen for collective self-defence to be lawful?", o:["The victim state of an armed attack must formally request help","The helper must get SC approval first","The GA must vote for it","The attacker must be a non-state actor"], a:0, why:"Same circumstances as individual self-defence, plus a formal request.", ref:"W9 s.56"},
{k:"case", q:"How did NATO justify bombing Yugoslavia in 1999?", o:["As a humanitarian intervention, without an SC mandate","Under an SC Art. 42 resolution","As self-defence after an attack on a NATO member","By Yugoslavia's invitation"], a:0, why:"'We act to protect thousands of innocent people' (Clinton).", ref:"W9 s.60"},
{k:"tf", q:"The Responsibility to Protect creates a new legal ground to use force without the Security Council.", o:["True","False"], a:1, why:"R2P works within the Charter; the SC remains the forum for authorising force.", ref:"W9 s.64"},
{k:"fact", q:"R2P's third pillar says that if a state manifestly fails to protect its people…", o:["The international community must be ready to act collectively, in line with the Charter","Any state may intervene alone","The state loses its UN seat","The ICJ takes over"], a:0, why:"Pillar 1: every state protects; pillar 2: others assist; pillar 3: collective action via the Charter.", ref:"W9 s.63"},
{k:"scenario", q:"In 1958 Jordan asked UK forces to come in because of internal disorder. Lawful?", o:["Yes: the territorial state consented; if consent is withdrawn, staying becomes unlawful","No: all foreign forces breach Art. 2(4)","Only with SC authorisation","Only under R2P"], a:0, why:"Intervention by invitation.", ref:"W9 s.66"},
{k:"compare", q:"Which method lets the parties choose the deciders, with a binding result that concerns only them?", o:["Arbitration","Judicial settlement","Mediation","Good offices"], a:0, why:"A court has a fixed composition and its decisions can also clarify IL generally.", ref:"W9 s.71"},
{k:"tf", q:"Once a state enters negotiations, it is legally obliged to reach a settlement.", o:["True","False"], a:1, why:"It must negotiate in good faith, but doesn't have to settle.", ref:"W9 s.69"},
{k:"compare", q:"A third party helps the disputing states get back to the table but does NOT take part in the talks. Which method?", o:["Good offices","Mediation","Arbitration","Conciliation"], a:0, why:"A mediator joins the talks and suggests terms; good offices don't.", ref:"W9 s.70"},
{k:"fact", q:"Can regional organisations (e.g. the African Union) take enforcement action?", o:["Yes, but only with explicit SC authorisation","Yes, freely","Never","Only with GA approval"], a:0, why:"Chapter VIII: settle local disputes first; enforcement needs SC authorisation.", ref:"W9 s.73"}
],

10: [
{k:"scenario", q:"Police shut down a peaceful newspaper for criticising the government. Which state duty is breached?", o:["The duty to respect","The duty to protect","The duty to fulfil","None"], a:0, why:"Respect = the state itself must not interfere.", eli:"Don't take the kid's lunch yourself.", ref:"W10 s.6"},
{k:"scenario", q:"A state does nothing while private factories force workers into slavery-like conditions. Which duty is breached?", o:["The duty to protect","The duty to respect","The duty to fulfil","No duty: they're private"], a:0, why:"Protect = stop third parties interfering with rights.", eli:"Don't let the bully take it.", ref:"W10 s.6"},
{k:"scenario", q:"A state builds schools and pays for free textbooks. Which duty is it carrying out?", o:["The duty to fulfil","The duty to respect","The duty to protect","Non-derogation"], a:0, why:"Fulfil = facilitate and provide.", ref:"W10 s.6"},
{k:"scenario", q:"A job requires all applicants to be over 180 cm tall, excluding most women without good reason. What form of discrimination?", o:["Indirect discrimination","Direct discrimination","Harassment","Victimisation"], a:0, why:"A rule for everyone that unfairly disadvantages a protected group.", ref:"W10 s.23"},
{k:"scenario", q:"An employee complains of harassment and is then demoted for complaining. What is this?", o:["Victimisation","Indirect discrimination","Affirmative action","Direct discrimination"], a:0, why:"Treating someone unfairly because they complained (retaliation).", ref:"W10 s.23"},
{k:"scenario", q:"A university reserves scholarships for low-income students. Is this discrimination?", o:["No: it is positive discrimination / affirmative action","Yes: direct discrimination","Yes: indirect discrimination","Yes: victimisation"], a:0, why:"Measures to improve the status of disadvantaged groups don't count as discrimination.", ref:"W10 s.27"},
{k:"tf", q:"The Universal Declaration of Human Rights (1948) is a legally binding treaty.", o:["True","False"], a:1, why:"Not legally binding, but the bedrock of IHRL. The binding versions are the ICCPR and ICESCR.", ref:"W10 s.11"},
{k:"fact", q:"What makes up the 'International Bill of Rights'?", o:["UDHR + ICCPR + ICESCR","UN Charter + UDHR","CRC + CEDAW + CRPD","The four Geneva Conventions"], a:0, why:"The declaration plus the two binding covenants.", ref:"W10 s.12"},
{k:"not", q:"Which is NOT a non-derogable right under Art. 4 ICCPR?", o:["Freedom of peaceful assembly","Right to life","Prohibition of torture","Freedom from slavery"], a:0, why:"Assembly can be reasonably limited. Non-derogable: life, recognition before law, thought/religion, no torture, slavery, retrospective crimes or prison for contract debts.", ref:"W10 s.16"},
{k:"scenario", q:"A poor state can't yet afford free education for all. What does the ICESCR require?", o:["Take steps in good faith towards it within its capacity","Nothing until it can afford it","Provide it immediately or face sanctions","Withdraw from the covenant"], a:0, why:"Progressive realisation (Art. 2(1) ICESCR).", ref:"W10 s.19"},
{k:"fact", q:"Which human rights treaty is the most ratified, per the slides?", o:["CRC (196)","CRPD (192)","CEDAW (189)","CMW (60)"], a:0, why:"The CMW (migrant workers) is the least ratified, at 60.", ref:"W10 s.14"},
{k:"compare", q:"Which instrument abolishes the death penalty for its parties?", o:["ICCPR Optional Protocol 2","ICCPR Optional Protocol 1","CRC Optional Protocol 1","CAT"], a:0, why:"OP1 lets individuals complain to the Human Rights Committee.", ref:"W10 s.30"},
{k:"fact", q:"What does CRC Optional Protocol 1 deal with?", o:["Child soldiers: no compulsory recruitment under 18","Sale of children","Individual complaints","Birth registration"], a:0, why:"OP2: sale of children; OP3: individual complaints.", ref:"W10 s.31"},
{k:"scenario", q:"A university installs ramps and gives extra exam time to a student with a disability. This is…", o:["Reasonable accommodation","Affirmative action quota","Progressive realisation","Derogation"], a:0, why:"Required under the CRPD.", ref:"W10 s.25"},
{k:"not", q:"Which is NOT a criterion for lawfully restricting a right?", o:["The restriction is popular in opinion polls","It is permitted in law","It is strictly necessary in a democratic society","No less intrusive means are available"], a:0, why:"Also: pressing social need; based on evidence, not arbitrary; limited, dignified, reviewable.", ref:"W10 s.34"},
{k:"compare", q:"When does human rights law apply, compared with IHL?", o:["Human rights: always; IHL: only in armed conflict","Both only in peacetime","Human rights only in war","IHL always; human rights only in peace"], a:0, why:"Distinct but complementary bodies of law.", ref:"W10 s.73"},
{k:"tf", q:"IHL applies only if the war itself was started lawfully.", o:["True","False"], a:1, why:"IHL applies regardless of the legality of the conflict, and equally to all parties.", ref:"W10 s.40"},
{k:"scenario", q:"Government forces fight an organised rebel group inside the country. What kind of conflict?", o:["Non-international armed conflict (NIAC)","International armed conflict (IAC)","Sporadic violence","Not an armed conflict"], a:0, why:"NIAC: state vs non-state armed group, or between armed groups.", ref:"W10 s.43"},
{k:"scenario", q:"A violent riot breaks out after a football match. Does IHL apply?", o:["No: sporadic violence isn't armed conflict","Yes: any violence triggers IHL","Yes, as a NIAC","Only Common Article 3 applies"], a:0, why:"IHL doesn't apply to riots, demonstrations or violent crime.", ref:"W10 s.43"},
{k:"scenario", q:"An enemy soldier drops his rifle and raises his hands to surrender. May he be shot?", o:["No: he is hors de combat","Yes: he is still a combatant","Yes, if he is from the aggressor state","Only if he was armed earlier"], a:0, why:"Killing or wounding someone hors de combat is prohibited.", ref:"W10 s.63"},
{k:"scenario", q:"An army attacks a busy market because enemy soldiers sometimes shop there. Which principle is violated?", o:["Distinction","Non-refoulement","Reciprocity","Progressive realisation"], a:0, why:"Attacks may be directed only at military objectives, never civilians or civilian objects.", ref:"W10 s.55"},
{k:"scenario", q:"An attack destroys an apartment block with 200 civilians to kill one low-ranking soldier. Which rule is breached?", o:["Proportionality (expected civilian harm is excessive)","Distinction only","Non-derogation","Nothing: the soldier was a target"], a:0, why:"AP I Art. 51(5)(b): harm must not be excessive compared with the military advantage.", ref:"W10 s.59"},
{k:"scenario", q:"Before bombing a weapons depot next to a school, the army gives an effective advance warning. Which principle?", o:["Precaution","Proportionality","Distinction","Military necessity"], a:0, why:"Precautions include constant care, verifying targets, choosing weapons and advance warnings.", ref:"W10 s.61"},
{k:"fact", q:"The four Geneva Conventions mainly apply in IACs. What is the exception?", o:["Common Article 3, which covers NIACs","Additional Protocol I","The Hague Conventions","The ICCPR"], a:0, why:"Common Article 3 is the 'mini-Geneva Convention' for non-international conflicts.", ref:"W10 s.50, s.69"},
{k:"tf", q:"IHL defines 'terrorism'.", o:["True","False"], a:1, why:"No IHL definition, but IHL prohibits typical terrorist acts (targeting civilians, hostage-taking, spreading terror).", ref:"W10 s.72"},
{k:"not", q:"Which is NOT a condition for militias to count as combatants?", o:["Being recognised by the enemy state","A chain of command","Carrying weapons openly","Following the laws and customs of war"], a:0, why:"Also uniforms. Even regular forces of an unrecognised nation are combatants.", ref:"W10 s.56"},
{k:"scenario", q:"During an armed conflict, a state suspends some IHL rules, citing a national emergency. Allowed?", o:["No: derogation is never allowed in IHL","Yes, like human rights derogations","Yes, if it notifies the UN","Only for 30 days"], a:0, why:"IHL is already the regime for the emergency; all rules apply all the time.", ref:"W10 s.47"},
{k:"scenario", q:"A party uses a hospital to store weapons. What happens to the hospital's protection?", o:["Protection may end because of misuse","It stays fully protected no matter what","It becomes a civilian object only","It must be handed to the ICRC"], a:0, why:"'Protection may end with misuse of medical facilities.'", ref:"W10 s.67"},
{k:"scenario", q:"A commander plans to attack a dam whose collapse would flood villages downstream. Per the slides?", o:["Prohibited: works containing 'dangerous forces'","Allowed if it has military value","Allowed with an advance warning","Allowed in a NIAC"], a:0, why:"One of the limits on means and methods of warfare.", ref:"W10 s.68"},
{k:"fact", q:"Which weapons treaty dates from 1997?", o:["Anti-Personnel Land Mines Convention","Chemical Weapons Convention","Biological Weapons Convention","Protocol on Blinding Laser Weapons"], a:0, why:"Biological 1972; Conventional 1980; Chemical 1993; Blinding Lasers 1995; Land Mines 1997.", ref:"W10 s.62"},
{k:"tf", q:"Treaty bodies' 'General Comments' explain specific treaty articles in more detail.", o:["True","False"], a:0, why:"Treaty bodies also consider state reports, receive complaints and run inquiries.", ref:"W10 s.28"}
]
};
